/*
 * build_name_bundle.js
 *
 * Regenerates the standalone "Grow Your Name" render bundle by slicing the
 * plant renderer + trait/haiku/name engine out of index.html into ONE
 * self-contained IIFE that a tiny /name page can load with no Firebase, no
 * auth, no onboarding, no 7MB app shell.
 *
 * WHY a generator and not a hand copy: the satellites went stale because they
 * were hand-copied (see memory project_skitterlings_stale_build_jun28). This
 * script re-derives the bundle from index.html every run, so it can never
 * silently drift. If the source ever moves, the anchor asserts below fail
 * LOUDLY instead of extracting the wrong lines.
 *
 * It extracts four contiguous segments (all live inside index.html's Block-7
 * main IIFE, all pure hash -> output with zero Firebase/DOM/network):
 *   1. TRAITS  : _PAL + hashToTraits + SEASON_DATA        (Block 5 core)
 *   2. SHA     : _sha256hex                                (name -> hash)
 *   3. RENDER  : _darkPlantBoost .. renderMythic          (the SVG art)
 *   4. HAIKU   : name banks glue + getPlantName + getHaiku + getTraitSummary
 *
 * Two exposure lines in the RENDER segment point at functions defined just
 * ABOVE the slice (buildAttentionPayload @15101, updateFocusPlant @15179);
 * neither is used by the render path, so they are neutralized.
 *
 * Output: name/render-bundle.js  (+ copies word-banks.js into name/)
 * Verify: node scripts/smoke_name.js
 *
 * Run: node scripts/build_name_bundle.js
 */
var fs = require('fs');
var path = require('path');

var ROOT = path.join(__dirname, '..');
var SRC = path.join(ROOT, 'index.html');
var OUT_DIR = path.join(ROOT, 'name');
var OUT_BUNDLE = path.join(OUT_DIR, 'render-bundle.js');
var WORD_BANKS_SRC = path.join(ROOT, 'word-banks.js');
var WORD_BANKS_OUT = path.join(OUT_DIR, 'word-banks.js');

var lines = fs.readFileSync(SRC, 'utf8').split('\n');

// --- anchor finder ---------------------------------------------------------
function findOne(substr, fromIdx) {
  var start = fromIdx || 0;
  var hits = [];
  for (var i = start; i < lines.length; i++) {
    if (lines[i].indexOf(substr) >= 0) hits.push(i);
  }
  if (hits.length === 0) {
    throw new Error('ANCHOR NOT FOUND: "' + substr + '" — index.html changed; update build_name_bundle.js');
  }
  return hits[0];
}
function assertUnique(substr) {
  var n = 0;
  for (var i = 0; i < lines.length; i++) if (lines[i].indexOf(substr) >= 0) n++;
  if (n !== 1) throw new Error('ANCHOR NOT UNIQUE (' + n + 'x): "' + substr + '"');
}

// TRAITS: _PAL .. window.SEASON_DATA = SEASON_DATA;
var traitsStart = findOne("var _PAL = ['pine','sage'");
var traitsEnd = findOne('window.SEASON_DATA = SEASON_DATA;', traitsStart); // inclusive

// SHA: async function _sha256hex(str){  ..  (up to, not incl, crossPollinateHashes)
var shaStart = findOne('async function _sha256hex(str){');
var shaEndExcl = findOne('async function crossPollinateHashes(hashA, hashB){', shaStart);

// RENDER: _darkPlantBoost flag .. (up to, not incl, the naming comment)
assertUnique('var _darkPlantBoost = false;');
assertUnique('var PALETTE = {');
var renderStart = findOne('var _darkPlantBoost = false;');
var namingComment = findOne('PROCEDURAL COLLECTIBLE NAMING'); // renderMythic ends just above this
var renderEndExcl = namingComment;

// HAIKU/NAME: naming comment .. (up to, not incl, greenhouse GH_KEY)
var haikuStart = namingComment;
var haikuEndExcl = findOne("var GH_KEY = 'sws_greenhouse';", namingComment);

// sanity: ranges must be ordered and non-empty
[['traits', traitsStart, traitsEnd + 1], ['sha', shaStart, shaEndExcl],
 ['render', renderStart, renderEndExcl], ['haiku', haikuStart, haikuEndExcl]]
  .forEach(function(seg) {
    if (!(seg[1] >= 0 && seg[2] > seg[1])) throw new Error('bad range for ' + seg[0] + ': ' + seg[1] + '..' + seg[2]);
  });

function slice(a, bExcl) { return lines.slice(a, bExcl); }

var traits = slice(traitsStart, traitsEnd + 1);
var sha = slice(shaStart, shaEndExcl);
var render = slice(renderStart, renderEndExcl).map(function(l) {
  var t = l.trim();
  if (t === 'window.buildAttentionPayload = buildAttentionPayload;')
    return '  /* [name-bundle] buildAttentionPayload exposure omitted (defined outside slice) */';
  if (t === 'window.updateFocusPlant = updateFocusPlant;')
    return '  /* [name-bundle] updateFocusPlant exposure omitted (defined outside slice) */';
  return l;
});
var haiku = slice(haikuStart, haikuEndExcl);

var header = [
  '/* AUTO-GENERATED by scripts/build_name_bundle.js — DO NOT EDIT BY HAND. */',
  '/* Regenerate: node scripts/build_name_bundle.js ; Verify: node scripts/smoke_name.js */',
  '/* Sliced from index.html. Loads AFTER word-banks.js (needs window._LW_BANKS). */',
  '(function(){',
  '  "use strict" === "use strict"; /* intentionally NOT strict mode (source is ES5 sloppy) */',
  '  if (typeof window !== "undefined" && !window.LW_VERSION) { window.LW_VERSION = "name-bundle"; }',
  ''
];
var footer = [
  '',
  '  /* [name-bundle] explicit window exposures — these fns are declared in the',
  '     slice but their window.* exposures live outside it in index.html. */',
  '  if (typeof getPlantName === "function") window.getPlantName = getPlantName;',
  '  if (typeof _sha256hex === "function") window._sha256hex = _sha256hex;',
  '  if (typeof getTraitSummary === "function") window.getTraitSummary = getTraitSummary;',
  '',
  '})();',
  ''
];

function banner(name, a, bExcl) {
  return ['', '/* ===== ' + name + ' (index.html lines ' + (a + 1) + '-' + bExcl + ') ===== */'];
}

var out = header
  .concat(banner('TRAITS', traitsStart, traitsEnd + 1)).concat(traits)
  .concat(banner('SHA256', shaStart, shaEndExcl)).concat(sha)
  .concat(banner('RENDER', renderStart, renderEndExcl)).concat(render)
  .concat(banner('HAIKU + NAME', haikuStart, haikuEndExcl)).concat(haiku)
  .concat(footer)
  .join('\n');

if (!fs.existsSync(OUT_DIR)) fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(OUT_BUNDLE, out, 'utf8');
fs.copyFileSync(WORD_BANKS_SRC, WORD_BANKS_OUT);

function kb(n) { return (n / 1024).toFixed(0) + ' KB'; }
console.log('Wrote ' + OUT_BUNDLE);
console.log('  TRAITS  lines ' + (traitsStart + 1) + '-' + (traitsEnd + 1) + '  (' + traits.length + ' lines)');
console.log('  SHA256  lines ' + (shaStart + 1) + '-' + shaEndExcl + '  (' + sha.length + ' lines)');
console.log('  RENDER  lines ' + (renderStart + 1) + '-' + renderEndExcl + '  (' + render.length + ' lines)');
console.log('  HAIKU   lines ' + (haikuStart + 1) + '-' + haikuEndExcl + '  (' + haiku.length + ' lines)');
console.log('  bundle  ' + kb(Buffer.byteLength(out)) + '  (raw)');
console.log('Copied  ' + WORD_BANKS_OUT + '  (' + kb(fs.statSync(WORD_BANKS_OUT).size) + ')');
